@@ -0,0 +1,9 @@
+<script>
+  let x = $state(0);
+  function key(e) { if (e.key === "ArrowRight") x = Math.min(x + 1, 20); }
+</script>
+<svelte:window onkeydown={key} />
+<h1>Snail Herder</h1>
+<p>The snail is {20 - x} steps from the lettuce.</p>
+<button onclick={() => (x = Math.min(x + 1, 20))} aria-label="Nudge the snail">🐌</button>
+{#if x === 20}<p>The snail is content.</p>{/if}
